WITH RECURSIVE x9 AS (SELECT 1 UNION ALL SELECT 1 + x8.v1849 FROM x11) SELECT x8.v1849, x8.v1849, (CASE WHEN LOCATE('year=\\\\"', x8.v1849) = 1 THEN SUBSTRING(x8.v1849, 6 + 1, LOCATE('\\\\"\\r', x8.v1849) - 6 - 1) ELSE CASE WHEN LOCATE('\\nyear=\\\\"', x8.v1849) THEN SUBSTRING(x8.v1849, LOCATE('\\nyear=\\\\"', x8.v1849) + 7, LOCATE('\\\\"\\r', SUBSTRING(x8.v1849, LOCATE('\\nyear=\\\\"', x8.v1849) + 7)) - 1) ELSE '' END END) AS x4, x8.v1849 FROM v1848 AS x8 WHERE EXISTS(SELECT 'x' FROM x10 WHERE x8.v1849 = x8.v1849)